import { z } from "zod";
const zHistoryProps = z.object({
    url: z.string().url(),
    route: z.string(),
});
export function History(define) {
    return define("History")
        .props(zHistoryProps)
        .shared({
        val: z.string().optional(),
        url: z.string().url(),
        route: z.string(),
    })
        .defaults((props) => ({
        val: undefined,
        url: props.url,
        route: props.route,
    }))
        .userEvents({
        PopState: [z.string().optional(), null],
    })
        .exposeSetter({ val: true })
        .render((props) => props);
}
export function PreventExit(define) {
    return define("PreventExit")
        .props(z.object({}))
        .render((props) => props);
}
